// #6de0ce (d990205ec6451251316de0ce) «באג: ניגודיות וטיפוגרפיה במסכי המועמד חורגות מ-AA ומהמסגרת».
// Строгий замер контраста WCAG по ТЕКСТОВЫМ УЗЛАМ (каждая строка текста — свой прямоугольник):
//  • цвет текста — computed color (через canvas, любой формат цвета) × альфа × opacity предков;
//  • фон — цепочка background-color предков до первого непрозрачного (полупрозрачные слои смешиваются);
//    если по дороге градиент / картинка / backdrop-filter / opacity < 1 / нет непрозрачного фона — фон берётся с
//    пикселей снимка окна с прозрачным текстом (каждый пиксель под строкой; итог — 10-й перцентиль, т. е. худшие 10 %
//    фона, одиночные пиксели иконок/рамок не решают);
//  • порог 4.5:1 для ЛЮБОГО текста (AC тикета: «כל טקסט… 4.5:1», крупный текст исключения не получает);
//  • текст под модальным листом (затемнён подложкой) не меряется — сверху другой слой (решение 15.10: не дефект);
//    так же — disabled / aria-hidden / inert / sr-only.
// Окно и все прокручиваемые блоки (лист согласия и т. п.) прокручиваются по высоте — меряется каждая строка в окне.
import { Page } from '@playwright/test';
import { contrast } from './a11y-support';

export const AA = 4.5;

type Rect = { x: number; y: number; w: number; h: number };
type Sample = {
  text: string;
  rects: Rect[];
  fg: number[]; // r,g,b,a — a уже с opacity предков
  bg: number[] | null; // непрозрачный фон по CSS, null → по пикселям
  bgWhy: string;
  fontSize: string;
  lineHeight: string;
};

export type Measured = { label: string; text: string; ratio: number; fg: string; bg: string; how: string };

/** Видимые строки текста в окне (верхний слой) с цветом и фоном по CSS. */
async function samples(page: Page): Promise<Sample[]> {
  return page.evaluate(() => {
    const cv = document.createElement('canvas');
    cv.width = cv.height = 1;
    const cx = cv.getContext('2d', { willReadFrequently: true })!;
    const rgba = (c: string): number[] => {
      cx.clearRect(0, 0, 1, 1);
      cx.fillStyle = '#000';
      cx.fillStyle = c;
      cx.fillRect(0, 0, 1, 1);
      const d = cx.getImageData(0, 0, 1, 1).data;
      return [d[0], d[1], d[2], d[3] / 255];
    };
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const out: Sample[] = [];
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
      const text = (n.textContent || '').replace(/\s+/g, ' ').trim();
      if (!text) continue;
      const el = n.parentElement;
      if (!el || /^(SCRIPT|STYLE|NOSCRIPT|TEMPLATE|OPTION)$/.test(el.tagName)) continue;
      if (el.closest('[aria-hidden=true],[inert],[disabled],[aria-disabled=true],.__qa')) continue;
      const er = el.getBoundingClientRect();
      if (er.width <= 2 || er.height <= 2) continue; // sr-only
      let op = 1;
      let hidden = false;
      let blend = false;
      for (let x: Element | null = el; x; x = x.parentElement) {
        const cs = getComputedStyle(x);
        if (cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse') hidden = true;
        op *= Number(cs.opacity);
        if (cs.mixBlendMode !== 'normal' || (cs.filter && cs.filter !== 'none')) blend = true;
      }
      if (hidden || op < 0.01) continue;
      const range = document.createRange();
      range.selectNodeContents(n);
      const rects = Array.from(range.getClientRects())
        .filter((r) => r.width > 1 && r.height > 1 && r.top >= 0 && r.left >= 0 && r.bottom <= vh && r.right <= vw)
        .map((r) => ({ x: r.left, y: r.top, w: r.width, h: r.height }));
      if (!rects.length) continue;
      // Верхний слой: в центре строки — сам элемент (или его потомок/предок), а не лист/подложка поверх.
      const c = rects[0];
      const hit = document.elementFromPoint(c.x + c.w / 2, c.y + c.h / 2);
      if (!hit || !(hit === el || el.contains(hit) || hit.contains(el))) continue;

      const cs = getComputedStyle(el);
      const fill = (cs as unknown as Record<string, string>).webkitTextFillColor;
      let fg = rgba(cs.color);
      if (fill && fill !== cs.color) {
        const f = rgba(fill);
        if (f[3] === 0 && cs.backgroundClip === 'text') continue; // градиентный текст — не наш случай
        fg = f;
      }
      fg = [fg[0], fg[1], fg[2], fg[3] * op];

      // Фон по CSS: до первого непрозрачного background-color.
      const layers: number[][] = [];
      let bg: number[] | null = null;
      let bgWhy = 'css';
      if (op < 0.999 || blend) bgWhy = 'pixels: opacity/filter у предков';
      for (let x: Element | null = el; x && bgWhy === 'css'; x = x.parentElement) {
        const xs = getComputedStyle(x);
        if (xs.backgroundImage && xs.backgroundImage !== 'none') bgWhy = `pixels: background-image у <${x.tagName.toLowerCase()}>`;
        else if (xs.backdropFilter && xs.backdropFilter !== 'none') bgWhy = 'pixels: backdrop-filter';
        else {
          const b = rgba(xs.backgroundColor);
          if (b[3] > 0) layers.push(b);
          if (b[3] >= 0.999) break;
        }
      }
      if (bgWhy === 'css') {
        if (!layers.length || layers[layers.length - 1][3] < 0.999) bgWhy = 'pixels: нет непрозрачного фона в предках';
        else {
          let base = layers[layers.length - 1].slice(0, 3);
          for (let i = layers.length - 2; i >= 0; i--) {
            const a = layers[i][3];
            base = base.map((v, k) => layers[i][k] * a + v * (1 - a));
          }
          bg = base;
        }
      }
      out.push({ text: text.slice(0, 50), rects, fg, bg, bgWhy, fontSize: cs.fontSize, lineHeight: cs.lineHeight });
    }
    return out;
  });
}

/** Пиксели фона под строками (снимок окна с прозрачным текстом) → для каждой строки 10-й перцентиль контраста. */
async function pixelRatios(page: Page, list: Sample[]): Promise<{ ratio: number; bg: number[] }[]> {
  const style = await page.addStyleTag({
    content:
      '*,*::before,*::after{color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important;caret-color:transparent!important;transition:none!important;animation-play-state:paused!important}::placeholder{color:transparent!important}',
  });
  let png: Buffer;
  try {
    png = await page.screenshot({ scale: 'css', animations: 'disabled' });
  } finally {
    await style.evaluate((s) => s.remove());
  }
  const probe = await page.context().newPage();
  try {
    await probe.setContent('<canvas></canvas>');
    return await probe.evaluate(
      async ({ b64, items }) => {
        const img = new Image();
        img.src = `data:image/png;base64,${b64}`;
        await img.decode();
        const c = document.querySelector('canvas')!;
        c.width = img.width;
        c.height = img.height;
        const ctx = c.getContext('2d', { willReadFrequently: true })!;
        ctx.drawImage(img, 0, 0);
        const lin = (v: number) => {
          const s = v / 255;
          return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
        };
        const L = (p: number[]) => 0.2126 * lin(p[0]) + 0.7152 * lin(p[1]) + 0.0722 * lin(p[2]);
        return items.map(({ rects, fg }) => {
          const ratios: number[] = [];
          const sum = [0, 0, 0];
          for (const r of rects) {
            const x = Math.max(0, Math.floor(r.x));
            const y = Math.max(0, Math.floor(r.y));
            const w = Math.max(1, Math.min(img.width - x, Math.floor(r.w)));
            const h = Math.max(1, Math.min(img.height - y, Math.floor(r.h)));
            const d = ctx.getImageData(x, y, w, h).data;
            for (let i = 0; i < d.length; i += 4) {
              const bg = [d[i], d[i + 1], d[i + 2]];
              const a = Math.min(1, fg[3]);
              const f = [0, 1, 2].map((k) => fg[k] * a + bg[k] * (1 - a));
              const [l1, l2] = [L(f), L(bg)].sort((p, q) => q - p);
              ratios.push((l1 + 0.05) / (l2 + 0.05));
              sum[0] += bg[0];
              sum[1] += bg[1];
              sum[2] += bg[2];
            }
          }
          ratios.sort((p, q) => p - q);
          const n = ratios.length || 1;
          return { ratio: ratios[Math.floor(n * 0.1)] ?? 0, bg: sum.map((v) => v / n) };
        });
      },
      { b64: png.toString('base64'), items: list.map(({ rects, fg }) => ({ rects, fg })) },
    );
  } finally {
    await probe.close();
  }
}

const css = (c: number[]) => `rgb(${c.slice(0, 3).map(Math.round).join(',')}${c.length > 3 && c[3] < 0.999 ? ` / ${c[3].toFixed(2)}` : ''})`;

/** Замер текущего положения прокрутки. */
async function measureView(page: Page, label: string): Promise<Measured[]> {
  const list = await samples(page);
  const pix = list.filter((s) => !s.bg);
  const pr = pix.length ? await pixelRatios(page, pix) : [];
  let j = 0;
  return list.map((s) => {
    if (s.bg) {
      const a = Math.min(1, s.fg[3]);
      const f = [0, 1, 2].map((k) => s.fg[k] * a + s.bg![k] * (1 - a));
      return { label, text: s.text, ratio: contrast(f, s.bg), fg: css(s.fg), bg: css(s.bg), how: 'css' };
    }
    const p = pr[j++];
    return { label, text: s.text, ratio: p.ratio, fg: css(s.fg), bg: `~${css(p.bg)}`, how: s.bgWhy };
  });
}

/**
 * Весь экран: окно и каждый прокручиваемый блок проходятся по высоте, на каждом шаге меряются все видимые строки.
 * Возвращает все замеры (по одному на текст — худший).
 */
export async function measureScreen(page: Page, label: string): Promise<Measured[]> {
  const worst = new Map<string, Measured>();
  const keep = (ms: Measured[]) => {
    for (const m of ms) {
      const prev = worst.get(m.text);
      if (!prev || m.ratio < prev.ratio) worst.set(m.text, m);
    }
  };
  const count = await page.evaluate(() => {
    document.querySelectorAll('[data-qa-scroll]').forEach((e) => e.removeAttribute('data-qa-scroll'));
    let i = 0;
    for (const e of Array.from(document.querySelectorAll('body *'))) {
      const el = e as HTMLElement;
      const cs = getComputedStyle(el);
      if (!/(auto|scroll)/.test(cs.overflowY) || el.scrollHeight <= el.clientHeight + 1 || el.clientHeight < 40) continue;
      if (el.closest('[inert],[aria-hidden=true]')) continue;
      el.setAttribute('data-qa-scroll', String(i++));
    }
    return i;
  });
  const targets: (number | null)[] = [null, ...Array.from({ length: count }, (_, i) => i)];
  for (const t of targets) {
    const { sh, ch } = await page.evaluate((t) => {
      const el = t === null ? document.scrollingElement! : (document.querySelector(`[data-qa-scroll="${t}"]`) as HTMLElement);
      return { sh: el.scrollHeight, ch: t === null ? window.innerHeight : el.clientHeight };
    }, t);
    for (let y = 0; ; y += Math.max(120, ch - 80)) {
      await page.evaluate(
        ([t, y]) => {
          const el = t === null ? document.scrollingElement! : (document.querySelector(`[data-qa-scroll="${t}"]`) as HTMLElement);
          el.scrollTop = y as number;
        },
        [t, y] as const,
      );
      keep(await measureView(page, label));
      if (y + ch >= sh) break;
    }
    await page.evaluate((t) => {
      const el = t === null ? document.scrollingElement! : (document.querySelector(`[data-qa-scroll="${t}"]`) as HTMLElement);
      el.scrollTop = 0;
    }, t);
  }
  return [...worst.values()];
}

export const fmt = (m: Measured) => `${m.label}: «${m.text}» ${m.ratio.toFixed(2)}:1 (текст ${m.fg} на ${m.bg}; ${m.how})`;

/** Стиль первого видимого элемента с текстом, начинающимся на `prefix`: цвет × opacity предков, размер, межстрочный. */
export async function textStyle(page: Page, prefix: string) {
  return page.evaluate((prefix) => {
    const el = Array.from(document.querySelectorAll('body *')).find((e) => {
      const own = Array.from(e.childNodes).filter((n) => n.nodeType === 3).map((n) => n.textContent || '').join('').trim();
      return own.startsWith(prefix) && (e as HTMLElement).getBoundingClientRect().width > 2;
    }) as HTMLElement | undefined;
    if (!el) return null;
    let op = 1;
    for (let x: Element | null = el; x; x = x.parentElement) op *= Number(getComputedStyle(x).opacity);
    const cs = getComputedStyle(el);
    return { color: cs.color, fill: (cs as unknown as Record<string, string>).webkitTextFillColor, opacity: op, fontSize: cs.fontSize, lineHeight: cs.lineHeight };
  }, prefix);
}
